mapper.select:
SELECT j.id, j.zkxmid, j.yssj, j.yhsj, j.jssj, j.sybz, j.skbz, j.jssj as syrq, x.zkpid, x.xmid as xmdm, z.zkpmc FROM zk_nyzkjg j LEFT JOIN zk_nyzkxm x ON j.zkxmid = x.zkxmid LEFT JOIN sys_zkpd z ON x.zkpid = z.zkpid WHERE 1=1
AND j.jssj >= DATE_SUB(CURDATE(), INTERVAL #{days} DAY) AND x.zkpid = #{zkpid}
AND DATE(j.jssj) = DATE(#{date}) AND x.zkpid = #{zkpid}
ORDER BY j.jssj DESC, j.id DESC

SELECT DATE_FORMAT(j.jssj, '%Y-%m') as month, COUNT(*) as cnt, AVG(j.yhsj) as mean, STDDEV(j.yhsj) as sd, CASE WHEN AVG(j.yhsj) > 0 THEN ROUND(STDDEV(j.yhsj) / AVG(j.yhsj) * 100, 2) ELSE 0 END as cv FROM zk_nyzkjg j LEFT JOIN zk_nyzkxm x ON j.zkxmid = x.zkxmid WHERE j.yhsj IS NOT NULL AND j.sybz = 1
AND j.zkxmid = #{zkxmid}
AND x.zkpid = #{zkpid}
AND j.jssj >= #{begDate}
AND j.jssj <= CONCAT(#{endDate}, ' 23:59:59')
GROUP BY month HAVING COUNT(*) >= 2 ORDER BY month

SELECT j.jssj as syrq, j.yhsj, CASE WHEN x.bzc IS NOT NULL AND x.bzc != '' AND x.bzc + 0 > 0 THEN ROUND((j.yhsj - x.bz + 0) / (x.bzc + 0), 4) ELSE ROUND((j.yhsj - sub.avg_val) / NULLIF(sub.sd_val, 0), 4) END as zscore FROM zk_nyzkjg j LEFT JOIN zk_nyzkxm x ON j.zkxmid = x.zkxmid LEFT JOIN ( SELECT zkxmid, AVG(yhsj) as avg_val, STDDEV(yhsj) as sd_val FROM zk_nyzkjg WHERE yhsj IS NOT NULL AND sybz = 1 GROUP BY zkxmid HAVING COUNT(*) >= 2 ) sub ON j.zkxmid = sub.zkxmid WHERE j.yhsj IS NOT NULL AND j.sybz = 1
AND j.zkxmid = #{zkxmid}
AND x.zkpid = #{zkpid}
AND j.jssj >= #{begDate}
AND j.jssj <= CONCAT(#{endDate}, ' 23:59:59')
ORDER BY j.jssj

SELECT COUNT(*) as total, SUM(CASE WHEN j.sybz = 1 THEN 1 ELSE 0 END) as valid, SUM(CASE WHEN j.sybz = 0 THEN 1 ELSE 0 END) as invalid, ROUND(AVG(j.yhsj), 4) as mean_val, ROUND(STDDEV(j.yhsj), 4) as sd_val, CASE WHEN AVG(j.yhsj) > 0 THEN ROUND(STDDEV(j.yhsj) / AVG(j.yhsj) * 100, 2) ELSE 0 END as cv_val, MIN(j.yhsj) as min_val, MAX(j.yhsj) as max_val FROM zk_nyzkjg j LEFT JOIN zk_nyzkxm x ON j.zkxmid = x.zkxmid WHERE j.yhsj IS NOT NULL
AND j.zkxmid = #{zkxmid}
AND x.zkpid = #{zkpid}
AND j.jssj >= #{begDate}
AND j.jssj <= CONCAT(#{endDate}, ' 23:59:59')
